BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(15);
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.section_offerings'::regclass AND conname='db03_handoff_section_class_source_key' AND contype='u' AND conkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.section_offerings'::regclass AND attname='id'),(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.section_offerings'::regclass AND attname='class_offering_id')]::smallint[]),'P40 unique Section plus Class source key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_section_same_class' AND contype='f' AND confrelid='app_private.section_offerings'::regclass AND conkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='section_offering_id'),(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='class_offering_id')]::smallint[] AND confkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.section_offerings'::regclass AND attname='id'),(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.section_offerings'::regclass AND attname='class_offering_id')]::smallint[]),'handoff Section must belong to exact Class Offering');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_section_same_class' AND confupdtype='r' AND confdeltype='r'),'P40 cross-domain lineage cannot update or delete referenced Section/Class');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.section_offerings'::regclass AND conname='d1_04_fk_02' AND contype='f'),'D1 Section-to-campus ancestry remains');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_grade_same_application' AND contype='f'),'P39 same-application Grade FK remains');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_identity_same_application' AND contype='f'),'P39 same-application identity FK remains');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_fee_same_application' AND contype='f'),'P39 same-application administrative fee FK remains');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='f' AND confrelid='app_private.admission_document_forwards'::regclass AND cardinality(conkey)=2),'P38 Forward/application lineage remains');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='u' AND cardinality(conkey)=1 AND conkey[1]=(SELECT attnum FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='application_id')),'one handoff per application remains');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_student_handoffs'::regclass),'P38 forced RLS remains');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgrelid='app_private.admission_student_handoffs'::regclass AND tgname='db03_handoff_mutation_disabled' AND NOT tgisinternal),'P38 handoff write-denial trigger remains');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('service_role','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_student_executor','app_private.admission_student_handoffs','INSERT'),'no client or server handoff writer introduced');
SELECT throws_ok($q$INSERT INTO app_private.admission_student_handoffs DEFAULT VALUES$q$,'P0001','DB03 atomic Student handoff writer unavailable','all attempted handoff writes are still denied');
SELECT ok((SELECT count(*)=2 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname IN('section_offering_id','class_offering_id') AND attnotnull AND NOT attisdropped),'both sides of class/section FK are required');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal APPROVE remains unavailable');
SELECT * FROM finish();
ROLLBACK;
